:root {
  --sand: #f0c97a;
  --sand-dark: #d4a843;
  --ocean: #2a7eb8;
  --ocean-light: #e8f4fd;
  --white: #ffffff;
  --text-dark: #1a3a52;
  --text-muted: #6b8a9e;
  --confirmed: #3db87a;
}

.contest-card {
  width: 340px;
  border: 2px solid var(--sand-dark);
  border-radius: 14px;
  overflow: hidden;
  background: var(--white);
  margin: 40px auto;
}

.card-header {
  background: var(--ocean);
  padding: 14px 20px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.event-label {
  font-size: 13px;
  color: var(--sand);
  font-weight: 600;
  letter-spacing: 0.04em;
}

.event-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--white);
  margin: 0;
  line-height: 1.1;
}

.entry-body {
  padding: 14px 20px;
  background: var(--ocean-light);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.entry-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.entry-key {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.entry-val {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-dark);
}

.category-badge {
  background: var(--sand);
  color: var(--text-dark);
  border-radius: 20px;
  padding: 2px 12px;
  font-size: 12px;
  font-weight: 700;
}

.card-footer {
  background: var(--white);
  border-top: 2px dashed var(--sand-dark);
  padding: 10px 20px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--confirmed);
}

.status-text {
  font-size: 13px;
  font-weight: 700;
  color: var(--confirmed);
  letter-spacing: 0.03em;
}
